import styled from '@emotion/styled';

export const StyledBrandBreakdownTable = styled.div({
  '.ag-row': {
    '.ag-cell': {
      '&[col-id="id"] .ag-cell-content': {
        minWidth: 0,
      },

      '&[col-id="id"] .ag-cell-content.align-left': {
        justifyContent: 'flex-start',
      },
    },
  },
});
